/*
 * QR encoding — a thin, typed wrapper around the `qrcode-generator` library.
 *
 * A QR code is generated by an explicit segment mode. The mode is *detected*
 * here using the rules from the QR specification so the UI never claims a mode
 * the encoder is not actually using:
 *   - Numeric      : digits only
 *   - Alphanumeric : the 45-character alphanumeric set
 *   - Byte         : everything else (UTF-8)
 *
 * Nothing in this file touches the DOM.
 */

import qrcodeGen from 'qrcode-generator';
import type { EcLevel, QrMode } from './types';

/** Error-correction levels, in the order the QR standard defines them. */
export const EC_LEVELS: EcLevel[] = ['L', 'M', 'Q', 'H'];

/** Human-facing descriptions of each error-correction level. */
export const EC_INFO: Record<
  EcLevel,
  { name: string; tagline: string; redundancy: string }
> = {
  L: {
    name: 'LOW',
    tagline: 'Smallest code, least redundancy.',
    redundancy: '≈7% recovery',
  },
  M: {
    name: 'MEDIUM',
    tagline: 'The standard default.',
    redundancy: '≈15% recovery',
  },
  Q: {
    name: 'QUARTILE',
    tagline: 'More redundancy, larger code.',
    redundancy: '≈25% recovery',
  },
  H: {
    name: 'HIGH',
    tagline: 'Maximum redundancy.',
    redundancy: '≈30% recovery',
  },
};

/**
 * Input limit. A version-40 QR at the weakest error correction can hold ~2953
 * bytes, so 1000 characters always fits in byte mode for ASCII input and keeps
 * rendering fast. Longer input is rejected with a readable message.
 */
export const MAX_INPUT = 1000;

/** Preloaded so the lab is explorable immediately. */
export const DEFAULT_TEXT = 'Hello, QRYX.';

/** A generated QR code: its module grid plus the parameters used to build it. */
export type QrMatrix = {
  size: number;
  version: number;
  ec: EcLevel;
  mode: QrMode;
  /** Row-major, 1 = dark module, 0 = light. Length is size × size. */
  modules: Uint8Array;
};

const NUMERIC_RE = /^[0-9]+$/;
const ALPHANUMERIC_RE = /^[0-9A-Z $%*+\-./:]+$/;

/** Determine the segment mode the encoder will use for this text. */
export function detectMode(text: string): QrMode {
  if (text.length === 0) return 'Byte';
  if (NUMERIC_RE.test(text)) return 'Numeric';
  if (ALPHANUMERIC_RE.test(text)) return 'Alphanumeric';
  return 'Byte';
}

/**
 * Encode `text` into a QR matrix.
 * Returns `null` when the text is empty or cannot fit a version-40 symbol —
 * callers show a readable error instead of crashing.
 */
export function encodeQr(
  text: string,
  ec: EcLevel,
  mode?: QrMode,
): QrMatrix | null {
  if (text.length === 0 || text.length > MAX_INPUT) return null;
  try {
    const m = mode ?? detectMode(text);
    const qr = qrcodeGen(0, ec);
    qr.addData(text, m);
    qr.make();
    const size = qr.getModuleCount();
    const modules = new Uint8Array(size * size);
    for (let r = 0; r < size; r++) {
      for (let c = 0; c < size; c++) {
        modules[r * size + c] = qr.isDark(r, c) ? 1 : 0;
      }
    }
    return { size, version: (size - 17) / 4, ec, mode: m, modules };
  } catch {
    return null;
  }
}

/** Count of dark modules — used for the observations panel and stats. */
export function countDark(modules: Uint8Array): number {
  let n = 0;
  for (let i = 0; i < modules.length; i++) if (modules[i]) n++;
  return n;
}
